import io.restassured.RestAssured;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;

import static io.restassured.RestAssured.given;
import static org.springframework.boot.test.context.SpringBootTest.WebEnvironment.RANDOM_PORT;

@SpringBootTest(webEnvironment = RANDOM_PORT)
class ZadaniaApiRestAssuredTest {

    @LocalServerPort
    private int port;

    @BeforeEach
    void skonfigurujPort() {
        RestAssured.port = port;
    }

    @Test
    void pobranieListyZadanZwracaStatusOk() {
        given()
            .when()
                .get("/api/zadania")
            .then()
                .statusCode(200);
    }
}

@Test
void utworzenieZadaniaZwraca201IAdresNowegoZasobu() {
    String nowaZadanieJson = """
        {
          "tytul": "Nauczyc sie REST Assured",
          "wykonane": false
        }
        """;

    given()
        .contentType("application/json")
        .body(nowaZadanieJson)
        .when()
            .post("/api/zadania")
        .then()
            .statusCode(201)
            .header("Location", org.hamcrest.Matchers.containsString("/api/zadania/"));
}

@Test
void pobranieListyZadan() {
    given()
        .when()
            .get("http://localhost:8080/api/zadania")   // BLEDNIE: port NA SZTYWNO
        .then()
            .statusCode(200);
}
// Z webEnvironment = RANDOM_PORT, aplikacja NAJCZESCIEJ uruchamia sie na
// INNYM porcie niz 8080 - test zakonczy sie 'Connection refused'

@SpringBootTest(webEnvironment = RANDOM_PORT)
class ZadaniaApiRestAssuredTest {

    @LocalServerPort
    private int port;

    @BeforeEach
    void skonfigurujPort() {
        RestAssured.port = port;   // POPRAWNIE: ZAWSZE aktualny, rzeczywisty port
    }

    @Test
    void pobranieListyZadan() {
        given().when().get("/api/zadania").then().statusCode(200);
    }
}
